import anthropic
client = anthropic.Anthropic()
cases = [("Refund request for order 123", "billing"), ("App crashes on login", "bug")]

def score(model):
    ok = 0
    for text, label in cases:
        r = client.messages.create(
            model=model, max_tokens=20,
            messages=[{"role": "user", "content": f"Classify as billing or bug. Reply with one word.\n{text}"}],
        )
        ok += r.content[-1].text.strip().lower() == label
    return ok / len(cases)

for m in ["claude-haiku-5-5", "claude-sonnet-5-5"]:
    print(m, score(m))

def pick_model(task):
    if task in {"classify", "extract", "route"}:
        return "claude-haiku-5-5"
    if task in {"code", "analysis", "content"}:
        return "claude-sonnet-5-5"
    if task in {"agentic_coding", "computer_use"}:
        return "claude-opus-5-5"
    return "claude-fable-5-1"  # long-horizon research / hardest reasoning

DEPRECATED_REPLACEMENTS = {
    "claude-sonnet-4-5-20250929": "claude-sonnet-5-5",
    "claude-opus-4-1-20250805": "claude-opus-4-8",
    "claude-3-haiku-20240307": "claude-haiku-4-5-20251001",
}

def resolve(model_id):
    if model_id in DEPRECATED_REPLACEMENTS:
        print(f"warning: {model_id} deprecated/retired, use {DEPRECATED_REPLACEMENTS[model_id]}")
    return model_id
